from mk import *

T = [0, 0.02, 0.04, 0.06, 0.08, 0.10, 0.12, 0.14, 0.16, 0.18, 0.20, 0.22]
Xcm = [0, 1.20, 2.88, 5.04, 7.68, 10.8, 14.4, 18.48, 23.04, 28.08, 33.60, 39.60]
vc = lambda i: (Xcm[i + 1] - Xcm[i - 1]) / 100 / (T[i + 1] - T[i - 1])  # central difference, m/s

def fig():
    g = Fig(560, 330, "טבלת מקום-זמן של גוף, מ-0 עד 0.22 שניות, וגרף המקום כפונקציה של הזמן")
    g.rect(20, 20, 150, 24 + 12 * 22, fill="none", width=1.5)
    g.line(95, 20, 95, 44 + 12 * 22, width=1.2); g.line(20, 44, 170, 44, width=1.2)
    g.text(57, 37, "t (s)"); g.text(132, 37, "x (cm)")
    for i, (t, x) in enumerate(zip(T, Xcm)):
        y = 44 + 22 * i + 16
        g.text(57, y, f"{t:g}", cls="dim"); g.text(132, y, f"{x:g}", cls="dim")
    X, Y = g.graph(240, 300, 270, 240, "t (s)", "x (cm)", xticks=[(t, f"{t:g}") for t in (0.04, 0.08, 0.12, 0.16, 0.2)], yticks=[(v, str(v)) for v in (10, 20, 30, 40)], xmax=0.24, ymax=45)
    g.curve(X, Y, lambda t: 48 * t + 600 * t * t, 0, 0.23)
    for t, x in zip(T, Xcm):
        g.dot(X(t), Y(x), 2.6)
    return g

def vtable():
    return table(["t (s)", "v (m/s)"], [["0.02", "0.72"], ["0.08", "1.44"], ["0.14", "2.16"], ["0.20", "2.88"]],
                 "טבלת התשובה: זמן ומהירות. 0.02 שנייה: 0.72 מטר לשנייה; 0.08: 1.44; 0.14: 2.16; 0.20: 2.88")

def vgraph():
    g = Fig(560, 300, "גרף התשובה: מהירות כפונקציה של זמן. ארבע נקודות מהטבלה על קו ישר עולה, שחותך את ציר המהירות ב-0.48 מטר לשנייה")
    X, Y = g.graph(70, 260, 420, 220, "t (s)", "v (m/s)", xticks=[(t, f"{t:g}") for t in (0.04, 0.08, 0.12, 0.16, 0.2)], yticks=[(v, f"{v:g}") for v in (0.5, 1, 1.5, 2, 2.5, 3)], xmax=0.23, ymax=3.2)
    g.plot(X, Y, [(0, 0.48), (0.22, 0.48 + 12 * 0.22)])
    for t in (0.02, 0.08, 0.14, 0.2):
        g.circle(X(t), Y(0.48 + 12 * t), 5, fill="var(--d-label)")
    g.text(X(0) + 8, Y(0.48) + 4, "0.48", cls="dim", anchor="start")
    return g

E(id="bagrut-1995-q1", year=1995, label="1995 שאלה 1", topic="kinematics", sub="kin-graphs", diff=3, fig=fig,
  stem=r"כדי לחקור את תנועתו של גוף שנע על קו ישר, רשם תלמיד את מקומו של הגוף במרווחי זמן של $0.02$ שניות. הוא הגדיר את הרגע שבו נערכה המדידה הראשונה כ-$t = 0$ (ברגע זה מהירות הגוף אינה בהכרח אפס) ואת ציר המקום $x$ בכיוון תנועת הגוף, כך שראשיתו בנקודה שבה הגוף נמצא ברגע $t = 0$. תוצאות המדידות רשומות בטבלה. לפי התוצאות סרטט התלמיד את הגרף של מקום הגוף כפונקציה של הזמן.",
  parts=[
    P("א", r"קבע לפי הגרף אם מהירות הגוף גדלה עם הזמן, קטנה או אינה משתנה. נמק.", choice(["גדלה", "קטנה", "אינה משתנה"], 0), ["graph", "understanding"], [
        X(r"המהירות היא השיפוע של גרף מקום-זמן."),
        S(r"בודקים איך השיפוע משתנה", r"הגרף נעשה תלול יותר ככל שהזמן עובר", r"\Delta x:\ 1.20,\ 1.68,\ 2.16,\ \dots\,\text{cm} \uparrow"),
    ], r"גדלה: הגרף נעשה תלול יותר, והגוף עובר יותר דרך בכל $0.02$ שניות", key=r"המהירות גדלה"),
    P("ב", r"חשב את מהירות הגוף ביחידות $\text{m/s}$ ברגע $t = 0.02\,\text{s}$. הסבר ופרט את חישוביך.", num(vc(1), "m/s", tol=2), ["graph", "units", "algebra"], [
        X(r"הגוף נע בתאוצה, ולכן גרף המקום-זמן הוא עקומה ולא קו ישר. את המהירות הרגעית אפשר היה למצוא מהשיפוע של המשיק לעקומה, אבל אין לנו גרף מדויק שאפשר למדוד עליו משיק. לכן נחשב מהטבלה: המהירות הרגעית ברגע מסוים שווה למהירות הממוצעת בפרק זמן שהרגע הזה נמצא בדיוק באמצעו (בתאוצה קבועה זה אפילו מדויק). שימו לב: לא מחלקים את המקום בזמן מההתחלה, כי בהתחלה המהירות אינה אפס."),
        S(r"בוחרים את הנקודות שלפני ואחרי", r"$t = 0$ ו-$t = 0.04\,\text{s}$, ו-$0.02$ באמצע ביניהן", r"x(0) = 0,\quad x(0.04) = 2.88\,\text{cm}"),
        S(r"מחשבים מהירות ממוצעת בפרק הזה", r"היא שווה למהירות הרגעית באמצע הפרק", r"v(0.02) = \frac{2.88 - 0}{0.04 - 0} = 72\,\text{cm/s}"),
        S(r"ממירים ל-$\text{m/s}$", r"מחלקים ב-$100$", r"v(0.02) = 0.72\,\text{m/s}"),
    ], r"$\approx 0.72\,\text{m/s}$", key=r"v0.02=0.6 m/s"),
    P("ג1", r"הכן טבלה עם עמודה של זמן $t\,(\text{s})$ ועמודה של גודל המהירות $v\,(\text{m/s})$. רשום בה את המהירות שחישבת עבור $t = 0.02\,\text{s}$, וחשב את המהירות ברגע $t = 0.08\,\text{s}$.", num(vc(4), "m/s", tol=2), ["graph", "algebra"], [
        S(r"נקודות לפני ואחרי", r"אותה שיטה כמו בסעיף ב", r"v(0.08) = \frac{x(0.10) - x(0.06)}{0.04} = \frac{10.8 - 5.04}{0.04} = 144\,\text{cm/s}"),
        S(r"ממירים", r"מחלקים ב-$100$", r"v(0.08) = 1.44\,\text{m/s}"),
        D(r"הטבלה המלאה (עם המהירויות של סעיפים ג2 ו-ג3)", vtable),
    ], r"$1.44\,\text{m/s}$", key=r"v0.08=0.96 m/s"),
    P("ג2", r"חשב את המהירות ברגע $t = 0.14\,\text{s}$.", num(vc(7), "m/s", tol=2), ["graph", "algebra"], [
        S(r"נקודות לפני ואחרי", r"אותה שיטה", r"v(0.14) = \frac{x(0.16) - x(0.12)}{0.04} = \frac{23.04 - 14.4}{0.04} = 216\,\text{cm/s} = 2.16\,\text{m/s}"),
    ], r"$2.16\,\text{m/s}$", key=r"v0.14=1.32 m/s"),
    P("ג3", r"חשב את המהירות ברגע $t = 0.20\,\text{s}$.", num(vc(10), "m/s", tol=2), ["graph", "algebra"], [
        S(r"נקודות לפני ואחרי", r"אותה שיטה", r"v(0.20) = \frac{x(0.22) - x(0.18)}{0.04} = \frac{39.60 - 28.08}{0.04} = 288\,\text{cm/s} = 2.88\,\text{m/s}"),
        D(r"הטבלה הסופית", vtable),
    ], r"$2.88\,\text{m/s}$", key=r"v0.2=1.68 m/s"),
    P("ד", r"סרטט גרף שמתאר את מהירות הגוף כפונקציה של הזמן.", OPEN, ["graph"], [
        S(r"מסמנים את הנקודות מהטבלה", r"ארבע נקודות: $(0.02, 0.72)$, $(0.08, 1.44)$, $(0.14, 2.16)$, $(0.20, 2.88)$", r"\frac{1.44 - 0.72}{0.06} = \frac{2.16 - 1.44}{0.06} = 12"),
        S(r"מעבירים קו", r"הנקודות על קו ישר אחד", r"v = 0.48 + 12t"),
        D(r"הגרף: מהירות כפונקציה של הזמן", vgraph),
    ], r"קו ישר עולה, שחותך את ציר המהירות ב-$0.48\,\text{m/s}$"),
    P("ה", r"האם תאוצת הגוף קבועה? אם לא, הסבר מדוע. אם כן, חשב את גודלה.", num(12, "m/s^2", tol=2), ["graph", "algebra"], [
        X(r"אם גרף המהירות הוא קו ישר, התאוצה קבועה ושווה לשיפוע."),
        S(r"מחשבים את השיפוע", r"הנקודה הראשונה והאחרונה", r"a = \frac{2.88 - 0.72}{0.20 - 0.02} = \frac{2.16}{0.18} = 12\,\text{m/s}^2"),
        C(r"בדיקה ישירה מהטבלה", r"בתאוצה קבועה ההפרש בין העתקים עוקבים קבוע: $a\,\Delta t^2$", r"\Delta(\Delta x) = 0.48\,\text{cm} \Rightarrow a = \frac{0.0048}{0.02^2} = 12\,\text{m/s}^2 \;\checkmark"),
    ], r"כן, $a = 12\,\text{m/s}^2$", key=r"6 m/s^2"),
    P("ו", r"אילו התלמיד היה מגדיר את ציר המקום $x$ בכיוון מנוגד לתנועת הגוף, האם סימן התאוצה ($+$ או $-$) היה שונה? הסבר.", choice(["כן, הסימן היה מתהפך", "לא, הסימן לא היה משתנה"], 0), ["signs", "understanding"], [
        X(r"הסימן של וקטור תלוי בכיוון הציר, לא בגוף."),
        S(r"בודקים את כיוון התאוצה", r"הגוף מאיץ בכיוון תנועתו. אם הציר החיובי נגד התנועה, גם המהירות וגם התאוצה שליליות", r"a = -12\,\text{m/s}^2"),
    ], r"כן: התאוצה בכיוון התנועה, ולכן מול ציר הפוך היא שלילית", key=r"כן, כיוון התאוצה היה מתהפך"),
  ],
  concepts=["טבלת מדידות", "מהירות רגעית מהעתק סביב הנקודה", "גרף מהירות-זמן", "תאוצה קבועה", "סימן לפי בחירת ציר"],
  summary=r"מנתוני מקום כל $0.02$ שניות מחשבים מהירויות רגעיות, בונים גרף מהירות ומוצאים את התאוצה.",
  note=r"מהירות ממוצעת מ-$t = 0$ עד $t$ היא לא המהירות ברגע $t$ (אלא באמצע הפרק). כדי למצוא מהירות רגעית לוקחים את הנקודות משני צדי הרגע.",
  review='אי-התאמה לדף התשובות, בסעיפים ב, ג ו-ה.\nבדף התשובות: המהירות ברגע 0.02 היא 0.6 מטר לשנייה, והתאוצה 6.\nאצלי: המהירות ברגע 0.02 היא 0.72 מטר לשנייה, והתאוצה 12.\nלמה: הגוף נע בתאוצה, ולכן את המהירות הרגעית מוצאים מהמהירות הממוצעת בפרק זמן שהרגע נמצא באמצעו: מ-0 עד 0.04 שניות. לפי הטבלה, ברגע 0.04 הגוף נמצא ב-2.88 ס"מ (לא 2.8), ולכן 2.88 ס"מ חלקי 0.04 שנייה = 72 ס"מ לשנייה = 0.72 מטר לשנייה. בדף התשובות חילקו את המקום בזמן מההתחלה (1.2 ס"מ חלקי 0.02 שנייה = 0.6). זה נכון רק אם הגוף מתחיל ממנוחה, ובשאלה כתוב במפורש שהמהירות בהתחלה אינה בהכרח אפס. בדיקה: ההפרש בין מקומות עוקבים בטבלה גדל כל פעם ב-0.48 ס"מ בדיוק, וזה נותן תאוצה 12.\nטעות הקלדה במקור: בטבלה במקור כתוב 00.4 במקום 0.04. אצלנו בטבלה כתוב 0.04.\nמה לבדוק: האם אתה מסכים שדף התשובות טעה. אם כן, אשר. אם אתה רוצה שהאתר יקבל את התשובות של דף התשובות, כתוב לי.')
